CREATE TABLE IF NOT EXISTS roles (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS permissions (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS user_roles (user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, role_id BIGINT NOT NULL REFERENCES roles(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (user_id, role_id));
CREATE TABLE IF NOT EXISTS role_permissions (role_id BIGINT NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission_id BIGINT NOT NULL REFERENCES permissions(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (role_id, permission_id));
CREATE TABLE IF NOT EXISTS forum_categories (id BIGSERIAL PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT, is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS forum_threads (id BIGSERIAL PRIMARY KEY, category_id BIGINT NOT NULL REFERENCES forum_categories(id), author_id TEXT NOT NULL REFERENCES "user"(id), slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PUBLISHED', is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS forum_posts (id BIGSERIAL PRIMARY KEY, thread_id BIGINT NOT NULL REFERENCES forum_threads(id) ON DELETE CASCADE, author_id TEXT NOT NULL REFERENCES "user"(id), body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PUBLISHED', is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS threats (id BIGSERIAL PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, summary TEXT NOT NULL, category TEXT NOT NULL, risk TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PUBLISHED', content JSONB NOT NULL DEFAULT '{}'::jsonb, author_id TEXT REFERENCES "user"(id), is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS scams (id BIGSERIAL PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, summary TEXT NOT NULL, category TEXT NOT NULL, risk TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PUBLISHED', content JSONB NOT NULL DEFAULT '{}'::jsonb, author_id TEXT REFERENCES "user"(id), is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS community_reports (id BIGSERIAL PRIMARY KEY, reporter_id TEXT REFERENCES "user"(id), subject_type TEXT NOT NULL, subject_id BIGINT NOT NULL, reason TEXT NOT NULL, details TEXT, status TEXT NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, actor_id TEXT REFERENCES "user"(id), action TEXT NOT NULL, entity_type TEXT, entity_id TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, request_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_settings (key TEXT PRIMARY KEY, value JSONB NOT NULL, updated_by TEXT REFERENCES "user"(id), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS forum_threads_category_idx ON forum_threads(category_id);
CREATE INDEX IF NOT EXISTS forum_posts_thread_idx ON forum_posts(thread_id);
CREATE INDEX IF NOT EXISTS threats_search_idx ON threats USING GIN (to_tsvector('simple', title || ' ' || summary));
CREATE INDEX IF NOT EXISTS audit_logs_created_at_idx ON audit_logs(created_at DESC);
